<script setup lang="ts">import type { PreviewResult } from "./types"; defineProps<{ open: boolean; preview: PreviewResult | null }>(); const emit = defineEmits<{ close: [] }>(); const format = (value: unknown) => JSON.stringify(value, null, 2);</script>
